#include <Wire.h>
#include <BH1750.h>

// Пины по схеме устройства
#define PIR_PIN 4   // D2 = GPIO4
#define LED_PIN 3   // D1 = GPIO3 -> MOSFET gate

BH1750 lightMeter;
bool hasBH1750 = false;

const float DARK_LUX = 15.0;      // ниже этого считаем темно
const unsigned long ON_TIME_MS = 30000; // 30 сек свечения после движения
unsigned long lastMotion = 0;
bool lightOn = false;

void fadeTo(int from, int to, int ms) {
  int steps = 30;
  for(int i=0;i<=steps;i++){
    int v = map(i,0,steps,from,to);
    ledcWrite(LED_PIN, v);
    delay(ms/steps);
  }
}

void setup(){
  Serial.begin(115200);
  pinMode(PIR_PIN, INPUT);
  // LEDC для XIAO ESP32-C3 Arduino 3.x
  ledcAttach(LED_PIN, 5000, 8);
  ledcWrite(LED_PIN, 0);

  Wire.begin(); // SDA=6 SCL=7 на XIAO C3
  if(lightMeter.begin(BH1750::CONTINUOUS_HIGH_RES_MODE)){
    hasBH1750 = true;
    Serial.println("BH1750 OK");
  } else {
    Serial.println("BH1750 not found - работаем только по PIR");
  }
}

void loop(){
  bool motion = digitalRead(PIR_PIN) == HIGH;
  float lux = hasBH1750 ? lightMeter.readLightLevel() : 0;
  bool isDark = hasBH1750 ? (lux < DARK_LUX) : true; // без датчика считаем всегда темно
  // если BH1750 вернул ошибку, читаем снова
  if(hasBH1750 && lux < 0) lux = 0;

  if(motion){
    lastMotion = millis();
    if(isDark && !lightOn){
      lightOn = true;
      Serial.printf("Motion lux=%.1f -> ON\n", lux);
      fadeTo(0,255,400);
    }
  }

  if(lightOn && (millis() - lastMotion > ON_TIME_MS)){
    // выключаем только если всё ещё темно? ночью выключаем по таймеру, днём тоже
    Serial.println("Timeout -> OFF");
    fadeTo(255,0,600);
    lightOn = false;
  }

  // если стало светло — сразу гасим
  if(lightOn && hasBH1750 && !isDark){
    fadeTo(255,0,400);
    lightOn = false;
  }

  delay(100);
}
